    ('rest_3718', 'Celeste', 'ChIJeyXilFZ3X0YR4cuEOlxrGcc', NULL, NULL),
    ('rest_3719', 'Dashi', 'ChIJPx3u7budX0YRB2JLoqpp-vQ', NULL, NULL),
    ('rest_3720', 'Ekstedt', 'ChIJhThAV1udX0YRWy5QWVtNNWY', NULL, NULL),
    ('rest_3721', 'ergo.', 'ChIJCYoQXG6dX0YRQvD9fggfOA0', NULL, NULL),
